    public static class NewWorldConnectionCorrection
    {
        const string ScenePath="Assets/CampMind/NewWorldGame/Camp.unity";
        const string Before="Assets/CampMind/NewWorldGame/StairsRepair/Before-20261017-214441.unity";
        const string Pristine="Assets/CampMind/NewWorldManualRepairs/20261017-201720/before-local-joins.unity";
        const string Folder="Assets/CampMind/NewWorldGame/ConnectionCorrection";
        static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));
        static string Output=>Path.Combine(Repo,"native/Artifacts/connection-correction");
        static JArray V(Vector3 v)=>new JArray(v.x,v.y,v.z);
        static string Key(Transform t)=>t.parent?Key(t.parent)+"/"+t.name:t.name;
        static MeshFilter[] Filters(Scene s)=>s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.sharedMesh).ToArray();
        static readonly Vector3 Foot=new Vector3(12.15f,4.5f,34.38f),Rim=new Vector3(18.69f,11.85f,42.10f);
        const string WorkFolder=Folder+"/v2";
        static Vector3 UpRoute=>Vector3.ProjectOnPlane(Rim-Foot,Vector3.up).normalized;
        static Vector3 Across=>Vector3.Cross(Vector3.up,UpRoute);
        static float StairRun=>Vector3.ProjectOnPlane(Rim-Foot,Vector3.up).magnitude;
        public static void RebuildConnections(){var scene=EditorSceneManager.OpenScene(ScenePath);EditorSceneManager.SaveScene(scene,Folder+"/Attempt-1.unity",true);var root=scene.GetRootGameObjects().First(g=>g.name=="绿色缺口与寨门连接修正");UnityEngine.Object.DestroyImmediate(root);var current=Filters(scene);var before=EditorSceneManager.OpenScene(Before,OpenSceneMode.Additive);foreach(var g in before.GetRootGameObjects())g.SetActive(false);var old=Filters(before).GroupBy(f=>Key(f.transform)).ToDictionary(g=>g.Key,g=>g.First());foreach(var f in current){if(!AssetDatabase.GetAssetPath(f.sharedMesh).StartsWith(Folder+"/"))continue;if(!old.TryGetValue(Key(f.transform),out var original))continue;f.sharedMesh=original.sharedMesh;var c=f.GetComponent<MeshCollider>();if(c)c.sharedMesh=f.sharedMesh;}EditorSceneManager.CloseScene(before,true);SceneManager.SetActiveScene(scene);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);RepairConnections();}
        public static void RepairConnections()
        {
            Directory.CreateDirectory(WorkFolder);AssetDatabase.Refresh();var scene=EditorSceneManager.OpenScene(ScenePath);if(scene.GetRootGameObjects().Any(g=>g.name=="绿色缺口与寨门连接修正"))throw new InvalidOperationException("Correction already installed");
            var protectedTransforms=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Select(t=>(t,t.position,t.rotation,t.localScale)).ToArray();
            var current=Filters(scene);var root=new GameObject("绿色缺口与寨门连接修正");var greenBox=new Bounds(new Vector3(2,0,30.5f),new Vector3(28,100,21));var gateBox=new Bounds(new Vector3(-14.5f,0,-49),new Vector3(29,100,34));
            var original=EditorSceneManager.OpenScene(Pristine,OpenSceneMode.Additive);foreach(var g in original.GetRootGameObjects())g.SetActive(false);var pristine=Filters(original);
            // Recover the original textured bank faces removed by the old repair,
            // rather than laying a broad flat plane over the terrace.
            int restored=0;foreach(string name in new[]{"Registered terrain section 0","village-relief","outer-bank-relief"}){var f=current.FirstOrDefault(v=>v.name==name);var old=pristine.FirstOrDefault(v=>v.name==name);if(!f||!old)continue;var world=World(f);var outside=StaticMeshClip.Subtract(world,new[]{greenBox,gateBox});UnityEngine.Object.DestroyImmediate(world);SetMesh(f,NewWorldSourceModules.Compact(outside),"retained-"+restored);UnityEngine.Object.DestroyImmediate(outside);var prior=World(old);foreach(var box in new[]{greenBox,gateBox}){var part=NewWorldSourceModules.KeepBounds(prior,box);if(part.triangles.Length==0){UnityEngine.Object.DestroyImmediate(part);continue;}Make("Restored original bank "+restored+" "+(box.center.z>0?"green":"gate"),part,old.GetComponent<Renderer>().sharedMaterials,root.transform,true,9);}UnityEngine.Object.DestroyImmediate(prior);restored++;}
            EditorSceneManager.CloseScene(original,true);SceneManager.SetActiveScene(scene);
            foreach(var t in protectedTransforms.Select(p=>p.t).Where(t=>t.name=="木桥寨门侧落地"||t.name=="Registered terrain section gate approach"||t.name=="主殿长阶下端落地"))t.gameObject.SetActive(false);
            var terrain=Filters(scene).Where(f=>f.gameObject.activeInHierarchy&&(f.name.StartsWith("Registered terrain section")||f.name.EndsWith("-relief")||f.name.StartsWith("Restored original bank")||f.name.StartsWith("Source terrain boulder detail")||f.name.StartsWith("observed-bank-rock-"))).ToArray();
            var terrainColliders=terrain.Select(f=>f.GetComponent<Collider>()).Where(c=>c&&c.enabled).ToArray();Physics.SyncTransforms();
            float Height(Vector3 p){var ray=new Ray(new Vector3(p.x,80,p.z),Vector3.down);var hits=terrainColliders.Select(c=>{bool found=c.Raycast(ray,out var h,160);return(found,h);}).Where(v=>v.found).ToArray();return hits.Length>0?hits.Max(v=>v.h.point.y):0;}
            var sf=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/CampMind/NewWorldCalibration/Models/stairs/main-hall-stairs.glb").GetComponentInChildren<MeshFilter>();var measuring=new GameObject("stair sampling");var sc=measuring.AddComponent<MeshCollider>();sc.sharedMesh=sf.sharedMesh;
            float StairHeight(float s){float sum=0;foreach(float o in new[]{-.24f,-.12f,0,.12f,.24f}){float x=Mathf.Lerp(-.4897984f,.4897019f,Mathf.Clamp01((s+o)/StairRun));x=Mathf.Clamp(x,-.48f,.48f);float y=-.1805f;if(sc.Raycast(new Ray(new Vector3(x,1,0),Vector3.down),out var h,2))y=h.point.y;sum+=Foot.y+(y+.1805f)/.3236f*(Rim.y-Foot.y);}return sum/5;}
            Vector3[] stairOutline=Rectangle(Foot,UpRoute,Across,0,StairRun-.03f,4.55f);var cuts=new List<Vector3[]>{stairOutline};
            var gateCenter=new Vector3(-12.3791866f,.12f,-48.9571533f);var bridgeEnd=new Vector3(-20.0373554f,.5375143f,-57.9547272f);var inside=new Vector3(-10,0,-38);var roadPoints=new[]{inside,gateCenter,bridgeEnd};
            var roadData=new List<(Vector3 a,Vector3 b,Vector3 f,Vector3 side,float length)>();for(int i=0;i<2;i++){var a=roadPoints[i];var b=roadPoints[i+1];var f=Vector3.ProjectOnPlane(b-a,Vector3.up).normalized;var side=Vector3.Cross(Vector3.up,f);float length=Vector3.ProjectOnPlane(b-a,Vector3.up).magnitude;roadData.Add((a,b,f,side,length));cuts.Add(Rectangle(a,f,side,-.12f,length+.12f,4.4f));}
            // Sample edges before cutting. Every bank strip reaches the existing
            // textured terrain exactly and closes the exposed side of the corridor.
            var groundMat=new Material(AssetDatabase.LoadAssetAtPath<Material>(NewWorldCalibrationBuilder.Folder+"/RoadProxy.mat"));groundMat.SetFloat("_UseVertexDirt",1);groundMat.SetFloat("_Dirt",1);groundMat.SetFloat("_RockSlope",1);AssetDatabase.CreateAsset(groundMat,WorkFolder+"/connection-ground.mat");
            foreach(int sign in new[]{-1,1}){var v=new List<Vector3>();var tri=new List<int>();var colors=new List<Color>();for(int i=0;i<=72;i++){float s=StairRun*i/72f;var center=Foot+UpRoute*s;var inner=center+Across*(sign*3.98f);inner.y=StairHeight(s)-.18f;var outer=center+Across*(sign*4.55f);outer.y=Height(outer);v.Add(inner);v.Add(outer);colors.Add(Color.black);colors.Add(Color.black);if(i>0)Quad(tri,v,(i-1)*2,(i-1)*2+1,i*2,i*2+1);}var m=MeshOf(v,tri);m.colors=colors.ToArray();Make("Green stair closed bank "+sign,m,new[]{groundMat},root.transform,true,9);}
            int roadId=0;foreach(var seg in roadData){var v=new List<Vector3>();var tri=new List<int>();var colors=new List<Color>();const int cross=16,along=56;for(int z=0;z<=along;z++){float t=z/(float)along;var p=Vector3.Lerp(seg.a,seg.b,t);for(int x=0;x<=cross;x++){float lateral=Mathf.Lerp(-4.4f,4.4f,x/(float)cross);var at=p+seg.side*lateral;float blend=Mathf.SmoothStep(0,1,Mathf.InverseLerp(2.85f,4.4f,Mathf.Abs(lateral)));at.y=Mathf.Lerp(p.y,Height(at),blend);v.Add(at);colors.Add(new Color(1-blend,0,0,1));if(z>0&&x>0){int n=z*(cross+1)+x;Quad(tri,v,n-cross-2,n-cross-1,n-1,n);}}}var m=MeshOf(v,tri);m.colors=colors.ToArray();Make("Gate continuous road "+roadId++,m,new[]{groundMat},root.transform,true,9);}
            int cutId=0;foreach(var f in terrain){var world=World(f);var cut=StaticMeshClip.SubtractAbovePolygons(world,cuts,Enumerable.Repeat(-40f,cuts.Count).ToArray());UnityEngine.Object.DestroyImmediate(world);var compact=NewWorldSourceModules.Compact(cut);UnityEngine.Object.DestroyImmediate(cut);SetMesh(f,compact,"connection-cut-"+cutId++);}
            var visible=UnityEngine.Object.Instantiate(sf.sharedMesh);visible.vertices=visible.vertices.Select(v=>Foot+UpRoute*((v.x+.4897984f)/.9795003f*StairRun)-Across*(v.z/.63367f*8f)+Vector3.up*((v.y+.1805f)/.3236f*(Rim.y-Foot.y))).ToArray();visible.RecalculateNormals();visible.RecalculateTangents();visible.RecalculateBounds();Make("Green opening stone staircase",visible,sf.GetComponent<Renderer>().sharedMaterials,root.transform,true,0);
            var walkV=new List<Vector3>();var walkT=new List<int>();for(int i=0;i<=120;i++){float s=StairRun*i/120f;var p=Foot+UpRoute*s;p.y=StairHeight(s);walkV.Add(p-Across*3.3f);walkV.Add(p+Across*3.3f);if(i>0)Quad(walkT,walkV,(i-1)*2,(i-1)*2+1,i*2,i*2+1);}Make("Green stair walk surface",MeshOf(walkV,walkT),null,root.transform,false,9);UnityEngine.Object.DestroyImmediate(measuring);
            bool preserved=protectedTransforms.All(p=>p.t.position==p.position&&p.t.rotation==p.rotation&&p.t.localScale==p.localScale);if(!preserved)throw new InvalidOperationException("Existing transform changed");
            var hall=Filters(scene).First(f=>f.transform.GetComponentsInParent<Transform>().Any(t=>t.name.StartsWith("Source-corrected H")));if(AssetDatabase.GetAssetPath(hall.sharedMesh)!="Assets/CampMind/NewWorldCalibration/corrected-H-0.asset")throw new InvalidOperationException("Original hall was not preserved");
            AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Physics.SyncTransforms();ExportAuthority();
            File.WriteAllText(Path.Combine(Output,"correction.json"),new JObject{["hallSourceMeshUntouched"]=true,["existingTransformsPreserved"]=true,["newStairOnlyInLowerOpening"]=true,["stairBottom"]=V(Foot),["stairTop"]=V(Rim),["stairWidth"]=8,["gateRoute"]=new JArray(roadPoints.Select(V)),["additionalTripoCredits"]=0,["runtimeVerified"]=false}.ToString());CaptureResults(scene);
        }
        static Vector3[] Rectangle(Vector3 a,Vector3 f,Vector3 side,float min,float max,float half)=>new[]{a+f*min-side*half,a+f*min+side*half,a+f*max+side*half,a+f*max-side*half};
        static Mesh World(MeshFilter f){var m=UnityEngine.Object.Instantiate(f.sharedMesh);m.vertices=m.vertices.Select(f.transform.TransformPoint).ToArray();m.normals=m.normals.Select(f.transform.TransformDirection).ToArray();m.RecalculateBounds();return m;}
        static void SetMesh(MeshFilter f,Mesh world,string id){world.vertices=world.vertices.Select(f.transform.InverseTransformPoint).ToArray();world.RecalculateNormals();world.RecalculateTangents();world.RecalculateBounds();AssetDatabase.CreateAsset(world,WorkFolder+"/"+id+".asset");f.sharedMesh=world;var c=f.GetComponent<MeshCollider>();if(c)c.sharedMesh=world;}
        static GameObject Make(string name,Mesh m,Material[] materials,Transform parent,bool render,int layer){AssetDatabase.CreateAsset(m,WorkFolder+"/"+name+".asset");var g=new GameObject(name);g.layer=layer;g.transform.SetParent(parent);g.AddComponent<MeshFilter>().sharedMesh=m;if(render)g.AddComponent<MeshRenderer>().sharedMaterials=materials;g.AddComponent<MeshCollider>().sharedMesh=m;return g;}
        static Mesh MeshOf(List<Vector3> v,List<int> t){var m=new Mesh{indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};m.SetVertices(v);m.SetTriangles(t,0);m.SetUVs(0,v.Select(p=>new Vector2(p.x*.1f,p.z*.1f)).ToList());m.RecalculateNormals();m.RecalculateBounds();return m;}
        static void Quad(List<int> t,List<Vector3> v,int a,int b,int c,int d){foreach(var tri in new[]{new[]{a,c,b},new[]{b,c,d}}){if(Vector3.Cross(v[tri[1]]-v[tri[0]],v[tri[2]]-v[tri[0]]).y<0)Array.Reverse(tri);t.AddRange(tri);}}
        public static void Build(){var scene=EditorSceneManager.OpenScene(ScenePath);var hall=Filters(scene).First(f=>f.transform.GetComponentsInParent<Transform>().Any(t=>t.name.StartsWith("Source-corrected H")));if(AssetDatabase.GetAssetPath(hall.sharedMesh)!="Assets/CampMind/NewWorldCalibration/corrected-H-0.asset")throw new InvalidOperationException("Protected original hall mesh changed");if(scene.GetRootGameObjects().Any(g=>g.activeInHierarchy&&(g.name.StartsWith("主殿新石阶")||g.name=="主殿上平台石阶接合")))throw new InvalidOperationException("Rejected upper-platform additions became active");Physics.SyncTransforms();ExportAuthority();var relative="native/Builds/NewWorld-Connections-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+"/CampMind.exe";var priorOutput=Environment.GetEnvironmentVariable("CAMP_NEW_WORLD_BUILD_OUTPUT");var priorDefer=Environment.GetEnvironmentVariable("CAMP_NEW_WORLD_DEFER_PROMOTION");try{Environment.SetEnvironmentVariable("CAMP_NEW_WORLD_BUILD_OUTPUT",relative);Environment.SetEnvironmentVariable("CAMP_NEW_WORLD_DEFER_PROMOTION","1");NewWorldGameInstaller.BuildGame();File.WriteAllText(Path.Combine(Output,"build.json"),new JObject{["success"]=true,["executable"]=Path.Combine(Repo,relative),["promotionDeferred"]=true}.ToString());}finally{Environment.SetEnvironmentVariable("CAMP_NEW_WORLD_BUILD_OUTPUT",priorOutput);Environment.SetEnvironmentVariable("CAMP_NEW_WORLD_DEFER_PROMOTION",priorDefer);}}
        public static void ExportAuthority()
        {
            var file=Path.Combine(Repo,"native/ArtSource/new-world-runtime.json");var data=JObject.Parse(File.ReadAllText(file));var before=JObject.Parse(File.ReadAllText(Path.Combine(Repo,"native/Artifacts/main-hall-stairs/authority-before-20261017-214441.json")));data["heights"]=before["heights"].DeepClone();data["walkable"]=before["walkable"].DeepClone();var heights=(JArray)data["heights"];var walk=(JArray)data["walkable"];int width=(int)data["width"],height=(int)data["height"];float step=(float)data["step"],minX=(float)data["minX"],minY=(float)data["minY"];int cells=0;
            for(int y=0;y<height;y++)for(int x=0;x<width;x++){var p=new Vector3(50-(minX+x*step),0,minY+y*step-50);bool hall=p.x>=-14&&p.x<=28&&p.z>=18&&p.z<=51;bool gate=p.x>=-44&&p.x<=4&&p.z>=-82&&p.z<=-29;if(!hall&&!gate)continue;int i=y*width+x;walk[i]=0;if(!Physics.Raycast(p+Vector3.up*100,Vector3.down,out var h,200,1<<9,QueryTriggerInteraction.Ignore))continue;heights[i]=(float)Math.Round(h.point.y,3);if((h.normal.y>=.65f||h.collider.name=="Original opening walk surface")&&!Physics.CheckCapsule(h.point+Vector3.up*.36f,h.point+Vector3.up*1.5f,.28f,1<<8,QueryTriggerInteraction.Ignore))walk[i]=1;cells++;}
            JObject Logical(Vector3 p)=>new JObject{["x"]=50-p.x,["y"]=p.z+50};data["stairRepair"]=new JObject{["bottom"]=Logical(Foot),["top"]=Logical(Rim),["porch"]=Logical(Rim),["scope"]="lower green opening only; original hall stairs and upper platform restored"};data["gateRepair"]=new JArray(Logical(new Vector3(-10,0,-38)),Logical(new Vector3(-12.3791866f,.12f,-48.9571533f)),Logical(new Vector3(-20.0373554f,.5375143f,-57.9547272f)));data["exportedUtc"]=DateTime.UtcNow.ToString("O");data["connectionCellsRefreshed"]=cells;File.WriteAllText(file,data.ToString(Newtonsoft.Json.Formatting.None));
            if(Filters(SceneManager.GetActiveScene()).Any(f=>f.name=="Original opening walk surface"&&f.gameObject.activeInHierarchy))ExportStairProfile();
        }
        static void ExportStairProfile(){var path=Path.Combine(Repo,"native/ArtSource/new-world-runtime.json");var data=JObject.Parse(File.ReadAllText(path));var filters=Filters(SceneManager.GetActiveScene());var f=filters.First(v=>v.name=="Original opening walk surface"&&v.gameObject.activeInHierarchy);var landing=filters.FirstOrDefault(v=>v.name=="Original hall stair contact"&&v.gameObject.activeInHierarchy);var colliders=landing?new[]{f.GetComponent<Collider>(),landing.GetComponent<Collider>()}:new[]{f.GetComponent<Collider>()};var end=landing?Rim+UpRoute*3:Rim;var profile=new JArray();for(int i=0;i<=240;i++){var p=Vector3.Lerp(Foot,end,i/240f);var hits=colliders.Select(c=>{bool ok=c.Raycast(new Ray(p+Vector3.up*60,Vector3.down),out var h,120);return(ok,h);}).Where(h=>h.ok).ToArray();if(hits.Length==0)throw new InvalidOperationException("Stair profile has a hole");profile.Add(hits.Max(h=>h.h.point.y));}data["stairRepair"]["halfWidth"]=landing?4.6f:5.7f;data["stairRepair"]["profile"]=profile;data["stairRepair"]["meshTop"]=new JObject{["x"]=50-Rim.x,["y"]=Rim.z+50};data["stairRepair"]["top"]=new JObject{["x"]=50-end.x,["y"]=end.z+50};File.WriteAllText(path,data.ToString(Newtonsoft.Json.Formatting.None));}
        public static void LandingAndBuild()
        {
            var scene=EditorSceneManager.OpenScene(ScenePath);var filters=Filters(scene);if(!filters.Any(f=>f.name=="Original hall stair contact")){var hall=filters.First(f=>f.transform.GetComponentsInParent<Transform>().Any(t=>t.name.StartsWith("Source-corrected H")));var temp=new GameObject("Original hall floor measurement");var col=temp.AddComponent<MeshCollider>();col.sharedMesh=World(hall);var v=new List<Vector3>();var t=new List<int>();for(int i=0;i<=60;i++){float s=Mathf.Lerp(-.15f,3.3f,i/60f);var p=Rim+UpRoute*s;if(!col.Raycast(new Ray(new Vector3(p.x,16,p.z),Vector3.down),out var h,30))throw new InvalidOperationException("Existing hall stair has no surface at "+p);p.y=Mathf.Lerp(Rim.y,h.point.y,Mathf.Clamp01((s+.15f)/.5f));v.Add(p-Across*4.8f);v.Add(p+Across*4.8f);if(i>0)Quad(t,v,(i-1)*2,(i-1)*2+1,i*2,i*2+1);}var root=new GameObject("原主殿自带台阶通行接缝 — 无可见模型改动");Make("Original hall stair contact",MeshOf(v,t),null,root.transform,false,9);UnityEngine.Object.DestroyImmediate(col.sharedMesh);UnityEngine.Object.DestroyImmediate(temp);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}Build();
        }
        public static void ClearStairHeadAndBuild()
        {
            var scene=EditorSceneManager.OpenScene(ScenePath);var f=Filters(scene).First(v=>v.name=="Original opening fitted stone stair");if(!AssetDatabase.GetAssetPath(f.sharedMesh).EndsWith("open-stair-head.asset")){var w=World(f);var outline=Rectangle(Foot,UpRoute,Across,StairRun*.72f,StairRun+.2f,4.75f);var cut=StaticMeshClip.SubtractAbovePolygon(w,outline,Rim.y+.08f);UnityEngine.Object.DestroyImmediate(w);var compact=NewWorldSourceModules.Compact(cut);UnityEngine.Object.DestroyImmediate(cut);SetMesh(f,compact,"open-stair-head");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}CaptureResults(scene);Build();
        }
        public static void FinishApronAndBuild()
        {
            var scene=EditorSceneManager.OpenScene(ScenePath);var root=new GameObject("绿区阶脚接地与石侧墙");var outline=Rectangle(Foot,UpRoute,Across,-4,.25f,6.5f);int id=0;foreach(var f in Filters(scene).Where(f=>f.gameObject.activeInHierarchy&&(f.name.StartsWith("Registered terrain section")||f.name.EndsWith("-relief")||f.name.StartsWith("Restored original bank")||f.name.StartsWith("Original green bank")||f.name.StartsWith("Source terrain boulder detail")||f.name.StartsWith("observed-bank-rock-")))){var w=World(f);var cut=StaticMeshClip.SubtractAbovePolygon(w,outline,-40);UnityEngine.Object.DestroyImmediate(w);var mesh=NewWorldSourceModules.Compact(cut);UnityEngine.Object.DestroyImmediate(cut);SetMesh(f,mesh,"apron-clear-"+id++);}
            var v=new List<Vector3>();var t=new List<int>();for(int i=0;i<=24;i++){float s=Mathf.Lerp(-4,.3f,i/24f);var p=Foot+UpRoute*s;p.y=Mathf.Lerp(.15f,.35f,Mathf.InverseLerp(-4,0,s));v.Add(p-Across*6.5f);v.Add(p+Across*6.5f);if(i>0)Quad(t,v,(i-1)*2,(i-1)*2+1,i*2,i*2+1);}Make("Original opening dirt foot approach",MeshOf(v,t),new[]{AssetDatabase.LoadAssetAtPath<Material>(WorkFolder+"/connection-ground.mat")},root.transform,true,9);
            var stone=new Material(AssetDatabase.LoadAssetAtPath<Material>(NewWorldCalibrationBuilder.Folder+"/NewStairStone.mat"));stone.SetColor("_BaseColor",new Color(.43f,.41f,.35f));AssetDatabase.CreateAsset(stone,WorkFolder+"/opening-side-stone.mat");foreach(var f in Filters(scene).Where(f=>f.gameObject.activeInHierarchy&&f.name.StartsWith("Original opening closed side")))f.GetComponent<Renderer>().sharedMaterial=stone;
            AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Physics.SyncTransforms();ExportAuthority();ExportStairProfile();CaptureResults(scene);Build();ExportStairProfile();
        }
        public static void PolishOpeningAndBuild()
        {
            var scene=EditorSceneManager.OpenScene(ScenePath);var walk=Filters(scene).First(f=>f.name=="Original opening walk surface").GetComponent<Collider>();Physics.SyncTransforms();int id=0;foreach(var f in Filters(scene).Where(f=>f.name.StartsWith("Original opening closed side")&&f.gameObject.activeInHierarchy)){var w=World(f);w.vertices=w.vertices.Select(p=>{float s=Mathf.Clamp(Vector3.Dot(p-Foot,UpRoute),0,StairRun);var at=Foot+UpRoute*s;if(walk.Raycast(new Ray(at+Vector3.up*60,Vector3.down),out var h,120))p.y=Mathf.Min(p.y,h.point.y+.08f);return p;}).ToArray();SetMesh(f,w,"polished-side-"+id++);}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);CaptureResults(scene);Build();ExportStairProfile();
        }
        public static void RaiseFootAndBuild()
        {
            if((bool?)JObject.Parse(File.ReadAllText(Path.Combine(Output,"correction.json")))["joinsOrdinaryGround"]==true){Build();return;}
            var scene=EditorSceneManager.OpenScene(ScenePath);int id=0;foreach(var f in Filters(scene).Where(f=>f.gameObject.activeInHierarchy&&(f.name=="Original opening fitted stone stair"||f.name=="Original opening walk surface"||f.name.StartsWith("Original opening closed side")||f.name=="Original opening dirt foot approach"))){var w=World(f);bool apron=f.name=="Original opening dirt foot approach";w.vertices=w.vertices.Select(p=>new Vector3(p.x,apron?Foot.y:Foot.y+(p.y-.35f)/(11.85f-.35f)*(Rim.y-Foot.y),p.z)).ToArray();SetMesh(f,w,"ground-level-final-"+id++);}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Physics.SyncTransforms();CaptureResults(scene);Build();ExportStairProfile();var report=JObject.Parse(File.ReadAllText(Path.Combine(Output,"correction.json")));report["stairBottom"]=V(Foot);report["joinsOrdinaryGround"]=true;File.WriteAllText(Path.Combine(Output,"correction.json"),report.ToString());
        }
