        public static void FinishBridgeVisualAndBuild(){var scene=EditorSceneManager.OpenScene(ScenePath);var filters=Filters(scene);var a=new Vector3(-20.0373554f,.5375143f,-57.9547272f);var b=new Vector3(-39.374176f,.2094273f,-73.21243f);var axis=Vector3.ProjectOnPlane(b-a,Vector3.up).normalized;var side=Vector3.Cross(Vector3.up,axis);float length=Vector3.ProjectOnPlane(b-a,Vector3.up).magnitude;var outline=Rectangle(a,axis,side,.04f,length-.04f,3.2f);int id=0;foreach(var f in filters.Where(f=>f.gameObject.activeInHierarchy&&(f.name.StartsWith("Registered terrain section")||f.name.EndsWith("-relief")||f.name.StartsWith("Restored original bank")||f.name.StartsWith("Source terrain boulder detail")||f.name.StartsWith("observed-bank-rock-")||f.name=="Gate rebuilt closed terrain"||f.name=="木桥外岸落地"))){var w=World(f);var cut=StaticMeshClip.SubtractAbovePolygon(w,outline,-40);UnityEngine.Object.DestroyImmediate(w);var compact=NewWorldSourceModules.Compact(cut);UnityEngine.Object.DestroyImmediate(cut);SetMesh(f,compact,"bridge-deck-visual-clear-"+id++);}var water=filters.First(f=>f.name=="river-new-flow-surface");var wm=World(water);var center=(a+b)*.5f;var nearby=wm.vertices.OrderBy(p=>(new Vector2(p.x-center.x,p.z-center.z)).sqrMagnitude).Take(8).ToArray();float level=nearby.Average(p=>p.y)-.02f;UnityEngine.Object.DestroyImmediate(wm);var v=new List<Vector3>{a+axis*1.5f-side*20,a+axis*1.5f+side*20,b-axis*1.5f-side*20,b-axis*1.5f+side*20};v=v.Select(p=>new Vector3(p.x,level,p.z)).ToList();var t=new List<int>();Quad(t,v,0,1,2,3);var root=new GameObject("木桥局部河面接续 — 原建筑不动");var patch=MeshOf(v,t);patch.uv=new[]{new Vector2(-20,0),new Vector2(20,0),new Vector2(-20,1),new Vector2(20,1)};patch.uv2=Enumerable.Repeat(new Vector2(length-3,.1f),4).ToArray();Make("Bridge local river continuity",patch,water.GetComponent<Renderer>().sharedMaterials,root.transform,true,4);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);CaptureResul