        public static void FitOriginalOpening()
        {
            var scene=EditorSceneManager.OpenScene(ScenePath);var root=new GameObject("原预留绿区石阶 — 按原台阶边界");var current=Filters(scene);foreach(var f in current.Where(f=>f.name.StartsWith("Green stair")||f.name=="Green opening stone staircase"))f.gameObject.SetActive(false);
            var box=new Bounds(new Vector3(2,0,30.5f),new Vector3(28,100,21));var targets=current.Where(f=>f.gameObject.activeInHierarchy&&(f.name.StartsWith("Registered terrain section")||f.name.EndsWith("-relief")||f.name.StartsWith("Restored original bank")&&f.name.EndsWith("green"))).ToArray();int id=0;
