            var oldScene=EditorSceneManager.OpenScene(Pristine,OpenSceneMode.Additive);foreach(var g in oldScene.GetRootGameObjects())g.SetActive(false);foreach(var f in Filters(oldScene).Where(f=>f.name=="Registered terrain section 0"||f.name=="village-relief"||f.name=="outer-bank-relief")){var w=World(f);var part=NewWorldSourceModules.KeepBounds(w,box);UnityEngine.Object.DestroyImmediate(w);if(part.triangles.Length>0)Make("Original green bank restored "+id++,part,f.GetComponent<Renderer>().sharedMaterials,root.transform,true,9);else UnityEngine.Object.DestroyImmediate(part);}EditorSceneManager.CloseScene(oldScene,true);SceneManager.SetActiveScene(scene);Physics.SyncTransforms();
            var terrain=Filters(scene).Where(f=>f.gameObject.activeInHierarchy&&(f.name.StartsWith("Registered terrain section")||f.name.EndsWith("-relief")||f.name.StartsWith("Restored original bank")||f.name.StartsWith("Original green bank")||f.name.StartsWith("Source terrain boulder detail")||f.name.StartsWith("observed-bank-rock-"))).ToArray();var cols=terrain.Select(f=>f.GetComponent<Collider>()).Where(c=>c).ToArray();float Height(Vector3 p){var hits=cols.Select(c=>{bool ok=c.Raycast(new Ray(p+Vector3.up*80,Vector3.down),out var h,160);return(ok,h);}).Where(h=>h.ok).ToArray();return hits.Length>0?hits.Max(h=>h.h.point.y):Mathf.Lerp(Foot.y,Rim.y,Mathf.Clamp01(Vector3.Dot(p-Foot,UpRoute)/StairRun));}
            var outline=Rectangle(Foot,UpRoute,Across,-.08f,StairRun+.03f,6.75f);foreach(var f in terrain){var w=World(f);var cut=StaticMeshClip.SubtractAbovePolygon(w,outline,-40);UnityEngine.Object.DestroyImmediate(w);var mesh=NewWorldSourceModules.Compact(cut);UnityEngine.Object.DestroyImmediate(cut);SetMesh(f,mesh,"original-opening-cut-"+id++);}
            var sf=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/CampMind/NewWorldCalibration/Models/stairs/main-hall-stairs.glb").GetComponentInChildren<MeshFilter>();var visible=UnityEngine.Object.Instantiate(sf.sharedMesh);visible.vertices=visible.vertices.Select(v=>Foot+UpRoute*((v.x+.4897984f)/.9795003f*StairRun)-Across*(v.z/.63367f*13f)+Vector3.up*((v.y+.1805f)/.3236f*(Rim.y-Foot.y))).ToArray();visible.RecalculateNormals();visible.RecalculateTangents();visible.RecalculateBounds();var stairs=Make("Original opening fitted stone stair",visible,sf.GetComponent<Renderer>().sharedMaterials,root.transform,true,0);var collider=stairs.GetComponent<Collider>();
            float Walk(float s){float sum=0;foreach(float d in new[]{-.18f,-.09f,0,.09f,.18f}){var p=Foot+UpRoute*Mathf.Clamp(s+d,0,StairRun);if(collider.Raycast(new Ray(p+Vector3.up*40,Vector3.down),out var h,80))sum+=h.point.y;else sum+=Mathf.Lerp(Foot.y,Rim.y,s/StairRun);}return sum/5;}
            var v=new List<Vector3>();var t=new List<int>();for(int i=0;i<=160;i++){float s=StairRun*i/160f;var p=Foot+UpRoute*s;p.y=Walk(s);v.Add(p-Across*5.8f);v.Add(p+Across*5.8f);if(i>0)Quad(t,v,(i-1)*2,(i-1)*2+1,i*2,i*2+1);}Make("Original opening walk surface",MeshOf(v,t),null,root.transform,false,9);
            var mat=AssetDatabase.LoadAssetAtPath<Material>(WorkFolder+"/connection-ground.mat");foreach(int sign in new[]{-1,1}){v=new List<Vector3>();t=new List<int>();for(int i=0;i<=80;i++){float s=StairRun*i/80f;var p=Foot+UpRoute*s;var a=p+Across*(sign*6.47f);a.y=Walk(s)-.12f;var b=p+Across*(sign*6.75f);b.y=Height(b);v.Add(a);v.Add(b);if(i>0)Quad(t,v,(i-1)*2,(i-1)*2+1,i*2,i*2+1);}Make("Original opening closed side "+sign,MeshOf(v,t),new[]{mat},root.transform,true,9);}
            AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Physics.SyncTransforms();ExportAuthority();CaptureResults(scene);var report=JObject.Parse(File.ReadAllText(Path.Combine(Output,"correction.json")));report["stairBottom"]=V(Foot);report["stairTop"]=V(Rim);report["stairWidth"]=13;report["originalReservedOpeningUsed"]=true;File.WriteAllText(Path.Combine(Output,"correction.json"),report.ToString());
