        public static void ResolvePassage()
        {
            var scene=EditorSceneManager.OpenScene(ScenePath);var filters=Filters(scene);if(filters.Any(f=>f.name=="Bridge source-matched walk surface"))throw new InvalidOperationException("Bridge seam already resolved");
            var points=new[]{new Vector3(-10,0,-38),new Vector3(-12.3791866f,.12f,-48.9571533f),new Vector3(-20.0373554f,.5375143f,-57.9547272f)};var roads=filters.Where(f=>f.gameObject.activeInHierarchy&&f.name.StartsWith("Gate continuous road")).OrderBy(f=>f.name).ToArray();
            for(int part=0;part<2;part++){var m=World(roads[part]);m.vertices=m.vertices.Select(p=>{for(int i=0;i<2;i++){var a=points[i];var d=Vector3.ProjectOnPlane(points[i+1]-a,Vector3.up);float t=Vector3.Dot(p-a,d)/d.sqrMagnitude;float lateral=Vector3.Dot(p-a,Vector3.Cross(Vector3.up,d.normalized));if(t>=-.01f&&t<=1.01f&&Mathf.Abs(lateral)<=2.9f)p.y=Mathf.Min(p.y,Mathf.Lerp(a.y,points[i+1].y,Mathf.Clamp01(t)));}return p;}).ToArray();m.RecalculateNormals();m.RecalculateBounds();if(part==0){var f=Vector3.ProjectOnPlane(points[2]-points[1],Vector3.up).normalized;var outline=Rectangle(points[1],f,Vector3.Cross(Vector3.up,f),-.12f,Vector3.ProjectOnPlane(points[2]-points[1],Vector3.up).magnitude+.12f,4.4f);var cut=StaticMeshClip.SubtractAbovePolygon(m,outline,-40);UnityEngine.Object.DestroyImmediate(m);m=NewWorldSourceModules.Compact(cut);UnityEngine.Object.DestroyImmediate(cut);}SetMesh(roads[part],m,"resolved-gate-road-"+part);}
            var bridge=filters.First(f=>f.name=="bridge(Clone)");var temp=new GameObject("bridge visual floor measurement");var wc=World(bridge);var sampler=temp.AddComponent<MeshCollider>();sampler.sharedMesh=wc;var inside=points[2];var outside=new Vector3(-39.374176f,.2094273f,-73.21243f);var axis=Vector3.ProjectOnPlane(outside-inside,Vector3.up).normalized;var side=Vector3.Cross(Vector3.up,axis);float length=Vector3.ProjectOnPlane(outside-inside,Vector3.up).magnitude;
            var verts=new List<Vector3>();var tri=new List<int>();for(int i=0;i<=100;i++){float s=Mathf.Lerp(-.3f,length+.3f,i/100f);var p=inside+axis*s;float sum=0;foreach(float offset in new[]{-.3f,0,.3f}){var q=inside+axis*Mathf.Clamp(s+offset,0,length);float h=Mathf.Lerp(inside.y,outside.y,Mathf.Clamp01(s/length));if(sampler.Raycast(new Ray(new Vector3(q.x,1.2f,q.z),Vector3.down),out var hit,5)&&hit.normal.y>.65f&&hit.point.y>-.2f&&hit.point.y<.9f)h=hit.point.y;sum+=h;}p.y=sum/3;verts.Add(p-side*1.65f);verts.Add(p+side*1.65f);if(i>0)Quad(tri,verts,(i-1)*2,(i-1)*2+1,i*2,i*2+1);}
            UnityEngine.Object.DestroyImmediate(temp);UnityEngine.Object.DestroyImmediate(wc);var root=scene.GetRootGameObjects().First(g=>g.name=="绿色缺口与寨门连接修正");Make("Bridge source-matched walk surface",MeshOf(verts,tri),null,root.transform,false,9);
            var core=Rectangle(inside,axis,side,-.3f,length+.3f,1.85f);int index=0;foreach(var f in filters.Where(f=>f.gameObject.activeInHierarchy&&(f.name.StartsWith("Restored original bank")||f.name.StartsWith("Registered terrain section")||f.name.EndsWith("-relief")||f.name.StartsWith("Source terrain boulder detail")))){if(!f.GetComponent<Renderer>()||!f.GetComponent<Renderer>().bounds.Intersects(new Bounds((inside+outside)*.5f,new Vector3(32,30,32))))continue;var m=World(f);var cut=StaticMeshClip.SubtractAbovePolygon(m,core,-40);UnityEngine.Object.DestroyImmediate(m);var compact=NewWorldSourceModules.Compact(cut);UnityEngine.Object.DestroyImmediate(cut);SetMesh(f,compact,"bridge-bank-clearance-"+index++);}
            AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Physics.SyncTransforms();ExportAuthority();CaptureResults(scene);
