        public static void SmoothGateTerrain()
        {
            var scene=EditorSceneManager.OpenScene(ScenePath);if(Filters(scene).Any(f=>f.name=="Gate rebuilt closed terrain"))throw new InvalidOperationException("Gate terrain already rebuilt");EditorSceneManager.SaveScene(scene,Folder+"/Before-gate-retopology.unity",true);
            var prior=EditorSceneManager.OpenScene(Pristine,OpenSceneMode.Additive);foreach(var g in prior.GetRootGameObjects())g.SetActive(false);var old=Filters(prior).First(f=>f.name=="Registered terrain section 0");var sampleMesh=World(old);var temp=new GameObject("gate original height measurement");var sampler=temp.AddComponent<MeshCollider>();sampler.sharedMesh=sampleMesh;
            var control=new[]{new Vector3(-10,0,-38),new Vector3(-12.3791866f,.12f,-48.9571533f),new Vector3(-20.0373554f,.5375143f,-57.9547272f)};var vertices=new List<Vector3>();var triangles=new List<int>();var colors=new List<Color>();const int nx=58,nz=68;var distances=new List<float>();
            for(int z=0;z<=nz;z++)for(int x=0;x<=nx;x++){var p=new Vector3(-29+x*.5f,0,-66+z*.5f);float nearest=float.PositiveInfinity,grade=0;for(int s=0;s<2;s++){var d=Vector3.ProjectOnPlane(control[s+1]-control[s],Vector3.up);float t=Mathf.Clamp01(Vector3.Dot(p-control[s],d)/d.sqrMagnitude);float gap=Vector3.ProjectOnPlane(p-(control[s]+d*t),Vector3.up).magnitude;if(gap<nearest){nearest=gap;grade=Mathf.Lerp(control[s].y,control[s+1].y,t);}}float original=grade;if(sampler.Raycast(new Ray(new Vector3(p.x,80,p.z),Vector3.down),out var hit,160))original=hit.point.y;float edge=Mathf.Min(x*.5f,(nx-x)*.5f,z*.5f,(nz-z)*.5f);float shoulder=grade+Mathf.Max(0,nearest-2.85f)*.45f;float target=nearest<2.85f?grade:Mathf.Lerp(Mathf.Min(original,shoulder),original,Mathf.SmoothStep(0,1,Mathf.InverseLerp(6,9,nearest)));p.y=Mathf.Lerp(original,target,Mathf.SmoothStep(0,1,Mathf.Clamp01(edge/2.5f)));vertices.Add(p);distances.Add(nearest);colors.Add(new Color(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(2.6f,4,nearest)),0,0,1));if(x>0&&z>0){int n=z*(nx+1)+x;Quad(triangles,vertices,n-nx-2,n-nx-1,n-1,n);}}
            for(int pass=0;pass<3;pass++){var heights=vertices.Select(p=>p.y).ToArray();for(int z=2;z<nz-1;z++)for(int x=2;x<nx-1;x++){int i=z*(nx+1)+x;if(distances[i]<2.9f)continue;var p=vertices[i];p.y=Mathf.Lerp(heights[i],(heights[i-1]+heights[i+1]+heights[i-nx-1]+heights[i+nx+1])*.25f,.5f);vertices[i]=p;}}
            UnityEngine.Object.DestroyImmediate(temp);UnityEngine.Object.DestroyImmediate(sampleMesh);EditorSceneManager.CloseScene(prior,true);SceneManager.SetActiveScene(scene);
            var m=MeshOf(vertices,triangles);m.colors=colors.ToArray();var fwd=Vector3.ProjectOnPlane(new Vector3(-39.374176f,0,-73.21243f)-control[2],Vector3.up).normalized;var opening=Rectangle(control[2],fwd,Vector3.Cross(Vector3.up,fwd),.02f,26,1.9f);var withoutBridge=StaticMeshClip.SubtractAbovePolygon(m,opening,-40);UnityEngine.Object.DestroyImmediate(m);m=NewWorldSourceModules.Compact(withoutBridge);UnityEngine.Object.DestroyImmediate(withoutBridge);
            var box=new Bounds(new Vector3(-14.5f,0,-49),new Vector3(29,100,34));int index=0;foreach(var f in Filters(scene).Where(f=>f.gameObject.activeInHierarchy&&(f.name.StartsWith("Restored original bank")||f.name.StartsWith("Registered terrain section")||f.name.EndsWith("-relief")||f.name.StartsWith("Source terrain boulder detail")||f.name.StartsWith("observed-bank-rock-")))){if(!f.GetComponent<Renderer>()||!f.GetComponent<Renderer>().bounds.Intersects(box))continue;var world=World(f);var cut=StaticMeshClip.Subtract(world,new[]{box});UnityEngine.Object.DestroyImmediate(world);var compact=NewWorldSourceModules.Compact(cut);UnityEngine.Object.DestroyImmediate(cut);if(compact.triangles.Length==0){f.gameObject.SetActive(false);UnityEngine.Object.DestroyImmediate(compact);}else SetMesh(f,compact,"gate-retopology-retained-"+index++);}
            foreach(var road in Filters(scene).Where(f=>f.name.StartsWith("Gate continuous road")))road.gameObject.SetActive(false);var root=scene.GetRootGameObjects().First(g=>g.name=="绿色缺口与寨门连接修正");Make("Gate rebuilt closed terrain",m,new[]{AssetDatabase.LoadAssetAtPath<Material>(WorkFolder+"/connection-ground.mat")},root.transform,true,9);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Physics.SyncTransforms();ExportAuthority();CaptureResults(scene);
