        static void CaptureResults(Scene scene){var camera=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Camera>()).First(c=>c.CompareTag("MainCamera"));Capture(camera,"corrected-overview.png");camera.transform.position=Foot-UpRoute*13+Vector3.up*11;camera.transform.LookAt(Rim+Vector3.up*1);camera.fieldOfView=65;Capture(camera,"green-stair-corrected.png");camera.transform.position=new Vector3(5,60,32);camera.transform.LookAt(new Vector3(5,0,32),Vector3.forward);camera.orthographic=true;camera.orthographicSize=26;Capture(camera,"corrected-hall-top.png");camera.orthographic=false;var gate=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<NewWorldGateDoor>()).First();gate.leftLeaf.rotation=gate.leftClosed*Quaternion.Euler(0,-105,0);gate.rightLeaf.rotation=gate.rightClosed*Quaternion.Euler(0,105,0);camera.transform.position=new Vector3(-10,5,-34);camera.transform.LookAt(new Vector3(-15,.5f,-53));camera.fieldOfView=65;Capture(camera,"gate-corrected.png");camera.transform.position=new Vector3(-22,18,-52);camera.transform.LookAt(new Vector3(-30,-1,-66));camera.fieldOfView=65;Capture(camera,"bridge-clearance-corrected.png");}
        public static void RestoreAndInspect()
        {
            Directory.CreateDirectory(Output);Directory.CreateDirectory(Folder);AssetDatabase.Refresh();var scene=EditorSceneManager.OpenScene(ScenePath);
            if(File.Exists(Path.Combine(Output,"restored.json")))throw new InvalidOperationException("Already restored; inspect the current correction instead of rolling back again");
            if(!File.Exists(Folder+"/Before-correction.unity"))EditorSceneManager.SaveScene(scene,Folder+"/Before-correction.unity",true);if(!File.Exists(Path.Combine(Output,"authority-before-correction.json")))File.Copy(Path.Combine(Repo,"native/ArtSource/new-world-runtime.json"),Path.Combine(Output,"authority-before-correction.json"));
            var transforms=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Select(t=>(t,t.position,t.rotation,t.localScale)).ToArray();
            var current=Filters(scene);var backup=EditorSceneManager.OpenScene(Before,OpenSceneMode.Additive);foreach(var root in backup.GetRootGameObjects())root.SetActive(false);var originals=Filters(backup).GroupBy(f=>Key(f.transform)).ToDictionary(g=>g.Key,g=>g.First());var restored=new JArray();
            foreach(var f in current){var path=AssetDatabase.GetAssetPath(f.sharedMesh);if(!path.StartsWith("Assets/CampMind/NewWorldGame/StairsRepair/",StringComparison.Ordinal))continue;if(!originals.TryGetValue(Key(f.transform),out var old))continue;f.sharedMesh=old.sharedMesh;var mc=f.GetComponent<MeshCollider>();if(mc)mc.sharedMesh=f.sharedMesh;restored.Add(new JObject{["object"]=Key(f.transform),["mesh"]=AssetDatabase.GetAssetPath(f.sharedMesh)});}
            EditorSceneManager.CloseScene(backup,true);SceneManager.SetActiveScene(scene);
            foreach(var root in scene.GetRootGameObjects().Where(g=>g.name.StartsWith("主殿新石阶")||g.name=="主殿上平台石阶接合"))root.SetActive(false);
            foreach(var t in transforms.Select(v=>v.t).Where(t=>t.name=="主殿长阶下端落地"||t.name.StartsWith("main-stair-")||t.name=="Observed long-stair stone side rail"||t.name.StartsWith("Long-stair stone guard")))t.gameObject.SetActive(false);
            bool preserved=transforms.All(p=>p.t.position==p.position&&p.t.rotation==p.rotation&&p.t.localScale==p.localScale);if(!preserved)throw new InvalidOperationException("Existing transform changed");
            EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText(Path.Combine(Output,"restored.json"),new JObject{["restoredMeshes"]=restored,["buildingTransformsPreserved"]=preserved,["hallSourceMeshRestored"]=true,["upperAdditionsDisabled"]=true}.ToString());Inspect();
        }
        public static void Inspect()
        {
            var inspectScene=EditorSceneManager.OpenScene(ScenePath);var stairAudit=new JArray();foreach(var f in Filters(inspectScene).Where(f=>f.name.StartsWith("main-stair-")||f.name=="main-hall-platform-observed-rim-and-foot")){var vertices=f.sharedMesh.vertices.Select(f.transform.TransformPoint).ToArray();float ymax=vertices.Max(p=>p.y);var top=vertices.Where(p=>p.y>ymax-.015f).ToArray();stairAudit.Add(new JObject{["name"]=f.name,["active"]=f.gameObject.activeInHierarchy,["min"]=V(vertices.Aggregate(Vector3.Min)),["max"]=V(vertices.Aggregate(Vector3.Max)),["topCenter"]=V(top.Aggregate(Vector3.zero,(a,b)=>a+b)/top.Length)});}File.WriteAllText(Path.Combine(Output,"original-opening.json"),stairAudit.ToString());
            Directory.CreateDirectory(Output);var scene=EditorSceneManager.OpenScene(ScenePath);var current=Filters(scene);var items=new JArray();foreach(var f in current.Where(f=>f.gameObject.activeInHierarchy)){var r=f.GetComponent<Renderer>();if(!r||!r.enabled)continue;if(!r.bounds.Intersects(new Bounds(new Vector3(0,10,30),new Vector3(65,50,60)))&&!r.bounds.Intersects(new Bounds(new Vector3(-15,6,-50),new Vector3(45,30,35))))continue;items.Add(new JObject{["name"]=f.name,["path"]=Key(f.transform),["mesh"]=AssetDatabase.GetAssetPath(f.sharedMesh),["min"]=V(r.bounds.min),["max"]=V(r.bounds.max)});}
            File.WriteAllText(Path.Combine(Output,"objects.json"),items.ToString());
            var hall=current.First(f=>f.transform.GetComponentsInParent<Transform>().Any(t=>t.name.StartsWith("Source-corrected H")));var hc=hall.gameObject.AddComponent<MeshCollider>();hc.sharedMesh=hall.sharedMesh;
            var ground=current.First(f=>f.name=="Registered terrain section 0").GetComponent<Collider>();
            var original=EditorSceneManager.OpenScene(Pristine,OpenSceneMode.Additive);foreach(var r in original.GetRootGameObjects())r.SetActive(false);var pristine=Filters(original).First(f=>f.name=="Registered terrain section 0");var sampleObject=new GameObject("pristine terrain measurement");sampleObject.transform.SetPositionAndRotation(pristine.transform.position,pristine.transform.rotation);sampleObject.transform.localScale=pristine.transform.lossyScale;var pc=sampleObject.AddComponent<MeshCollider>();pc.sharedMesh=pristine.sharedMesh;
            var rows=new JArray();float? Hit(Collider c,Vector3 p,float ceiling){var ray=new Ray(new Vector3(p.x,ceiling,p.z),Vector3.down);return c.Raycast(ray,out var hit,200)?(float?)hit.point.y:null;}
            foreach(bool gate in new[]{false,true}){int minX=gate?-36:-15,maxX=gate?4:30,minZ=gate?-72:15,maxZ=gate?-25:51;for(int z=minZ;z<=maxZ;z++)for(int x=minX;x<=maxX;x++){var p=new Vector3(x,0,z);var row=new JObject{["region"]=gate?"gate":"hall",["x"]=x,["z"]=z};var h=Hit(ground,p,80);if(h.HasValue)row["current"]=h.Value;h=Hit(pc,p,80);if(h.HasValue)row["pristine"]=h.Value;if(!gate){h=Hit(hc,p,16);if(h.HasValue)row["hall"]=h.Value;}rows.Add(row);}}
            File.WriteAllText(Path.Combine(Output,"surface-samples.json"),rows.ToString());UnityEngine.Object.DestroyImmediate(hc);UnityEngine.Object.DestroyImmediate(sampleObject);EditorSceneManager.CloseScene(original,true);SceneManager.SetActiveScene(scene);
            var g=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<NewWorldGateDoor>()).First();File.WriteAllText(Path.Combine(Output,"gate.json"),new JObject{["center"]=V(g.center),["leftLeafMin"]=V(g.leftLeaf.GetComponentInChildren<Renderer>().bounds.min),["rightLeafMin"]=V(g.rightLeaf.GetComponentInChildren<Renderer>().bounds.min)}.ToString());
            var camera=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Camera>()).First(c=>c.CompareTag("MainCamera"));Capture(camera,"restored-overview.png");camera.transform.position=new Vector3(-12,17,13);camera.transform.LookAt(new Vector3(7,7,35));camera.fieldOfView=62;Capture(camera,"reserved-opening.png");camera.transform.position=new Vector3(5,60,32);camera.transform.LookAt(new Vector3(5,0,32),Vector3.forward);camera.orthographic=true;camera.orthographicSize=26;Capture(camera,"hall-top.png");camera.orthographic=false;camera.transform.position=g.center+new Vector3(8,7,12);camera.transform.LookAt(g.center+new Vector3(-6,0,-7));camera.fieldOfView=65;Capture(camera,"gate-before.png");
        }
        static void Capture(Camera c,string name){var rt=new RenderTexture(1672,941,24);c.targetTexture=rt;c.Render();RenderTexture.active=rt;var texture=new Texture2D(1672,941,TextureFormat.RGB24,false);texture.ReadPixels(new Rect(0,0,1672,941),0,0);texture.Apply();File.WriteAllBytes(Path.Combine(Output,name),texture.EncodeToPNG());c.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(texture);UnityEngine.Object.DestroyImmediate(rt);}
    }
